    - { choose: 2, categories: ["Weapon Proficiencies"], note: "W.P.: two of choice." }
    - { name: "Hand to Hand: Basic", base: 0, per_level: 0, note: "May be changed to Expert at the cost of one O.C.C. Related skill, or to Martial Arts at the cost of two." }
  occ_related_skills:
    count: 7
    categories:
      - { name: "Communications", bonus: 10 }
      - "Domestic"
      - { name: "Espionage", bonus: 5 }
      - { name: "Medical", only: ["First Aid", "Paramedic"] }
      - "Physical"
      - "Pilot"
      - "Pilot Related"
      - { name: "Rogue", bonus: 5 }
      - { name: "Science", bonus: 5 }
      - { name: "Technical", bonus: 5 }
      - "Weapon Proficiencies"
    schedule: [{ level: 3, count: 2 }, { level: 6, count: 1 }, { level: 9, count: 1 }, { level: 12, count: 1 }]
    note: "Select seven other skills, plus two more at level three and one each at levels six, nine and twelve. All new skills start at level one proficiency. The book bars Electrical, Mechanical, Military and Wilderness outright, so those four categories are absent rather than listed as none."
  secondary_skills:
    count: 4
    note: "Four secondary skills from the same list, without the bonuses in parentheses, starting at the base skill level. The any/only/none limits above still apply."
equipment_starting:
  - { item_id: "hand-held-computer", qty: 1 }
  - { item_id: "clothing", qty: 1 }
  - { item_id: "hi-10-heavy-laser-pistol", qty: 1 }
  - { item_id: "tvia-badge-and-id", qty: 1 }
  - { item_id: "light-combat-armor", qty: 1 }
extraction_notes: |
  - Read from the OCR cache of a scan; the stat block runs from printed 59 onto
